// One-shot script: extract every AcroForm field from the USCIS I-130 PDF
// using Mozilla's PDF.js (pdfjs-dist). The official I-130 is a hybrid
// AcroForm/XFA dynamic form generated by Adobe LiveCycle, which pdf-lib
// cannot fully parse — pdfjs-dist is more permissive and exposes the
// widget annotations + XFA datasets we need.
//
// Emits:
//   src/i130-engine/data/fields.raw.json — full dump
//   stdout — summary counts by type and Part
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
// Legacy build is the Node-compatible bundle.
const pdfjs = require('pdfjs-dist/legacy/build/pdf.mjs');

const pdfPath = 'src/i130-engine/data/uscis-i130-form.pdf';
const outPath = 'src/i130-engine/data/fields.raw.json';

const data = new Uint8Array(readFileSync(pdfPath));
const loadingTask = pdfjs.getDocument({
  data,
  // Silence verbose console warnings during dump
  verbosity: 0,
  // Enable XFA so we can see XFA-only fields too
  enableXfa: true,
});

const doc = await loadingTask.promise;
const numPages = doc.numPages;
console.log(`Pages: ${numPages}`);

const metadata = await doc.getMetadata().catch(() => null);
if (metadata?.info) {
  console.log('Info:', {
    Title: metadata.info.Title,
    Subject: metadata.info.Subject,
    Producer: metadata.info.Producer,
    Creator: metadata.info.Creator,
    CreationDate: metadata.info.CreationDate,
    ModDate: metadata.info.ModDate,
  });
}

// Collect widget annotations across every page. Each form widget shows up
// once per page where it appears; we dedupe by fieldName.
const seen = new Map();
const orderedNames = [];

for (let pageNum = 1; pageNum <= numPages; pageNum++) {
  const page = await doc.getPage(pageNum);
  const annotations = await page.getAnnotations({ intent: 'display' });
  for (const a of annotations) {
    if (a.subtype !== 'Widget') continue;
    const name = a.fieldName || a.alternativeText || '(unnamed)';
    if (!seen.has(name)) {
      orderedNames.push(name);
      seen.set(name, {
        name,
        type: a.fieldType || 'Unknown',         // Tx, Btn, Ch, Sig
        flags: a.fieldFlags ?? 0,
        readOnly: a.readOnly ?? false,
        required: a.required ?? false,
        multiline: a.multiLine ?? false,
        maxLen: a.maxLen ?? null,
        radioButton: a.radioButton ?? false,
        checkBox: a.checkBox ?? false,
        pushButton: a.pushButton ?? false,
        combo: a.combo ?? false,
        options: a.options ?? null,
        buttonValue: a.buttonValue ?? null,
        defaultValue: a.defaultFieldValue ?? null,
        firstPage: pageNum,
      });
    }
  }
}

const dump = orderedNames.map((n) => seen.get(n));

writeFileSync(outPath, JSON.stringify(dump, null, 2));

// Type rollup
const byType = {};
for (const f of dump) {
  let t = f.type;
  if (t === 'Btn') {
    if (f.checkBox) t = 'CheckBox';
    else if (f.radioButton) t = 'Radio';
    else if (f.pushButton) t = 'PushButton';
    else t = 'Btn(other)';
  } else if (t === 'Tx') {
    t = 'Text';
  } else if (t === 'Ch') {
    t = f.combo ? 'ComboBox' : 'ListBox';
  } else if (t === 'Sig') {
    t = 'Signature';
  }
  byType[t] = (byType[t] || 0) + 1;
}

// Part rollup — USCIS uses naming like form1[0].#subform[0].Pt1Line1a_FamilyName[0]
const buckets = {};
for (const f of dump) {
  const m = f.name.match(/Pt(\d+)/i);
  const key = m ? `Part ${m[1]}` : 'Other';
  buckets[key] = (buckets[key] || 0) + 1;
}

console.log(`\nTotal unique fields: ${dump.length}`);
console.log('By type:', byType);
console.log('By Part (Pt<N> prefix):', buckets);
console.log(`\nFirst 5 field names:`);
for (const f of dump.slice(0, 5)) console.log(`  ${f.name}`);
console.log(`\nWrote: ${outPath}`);
